_TR = dict(zip("абвгдеёжзийклмнопрстуфхцчшщъыьэюя", ["a","b","v","g","d","e","e","zh","z","i","j","k","l","m","n","o","p","r","s","t","u","f","h","c","ch","sh","sch","","y","","e","yu","ya"]))
def gloss_slug(term):
    import unicodedata, re as _r
    t = term.lower().split("(")[0].strip()
    t = "".join(_TR.get(ch, ch) for ch in t)
    t = unicodedata.normalize("NFKD", t).encode("ascii", "ignore").decode()
    return _r.sub(r"[^a-z0-9]+", "-", t).strip("-")

def gloss_merge(sections, lg):
    """sections: list of (title, [(term, def)]) — returns a new list with the extra terms appended per section."""
    out = []
    for i, (sec, items) in enumerate(sections):
        out.append((sec, list(items) + GLOSS_EXTRA[lg].get(i, [])))
    return out
